"""Independent completed HWC replay audit, without executing Coq or QCP.
Reconstructs actual fields, full interfaces, ordinary sources and Print responses.
"""
from pathlib import Path
import json,re
from package_checks import sha,read,require,check_inputs
import full_inputs as I
import context as X
import assumptions,gate_sources as G,external_dependencies
NS='HwcConv'
def validate(case,run,h,f):
 case,run=Path(case).resolve(),Path(run).resolve();I.configure(case)
 require(h['complete_handoff']is True and h['namespace']==NS,'Complete HwcConv inputs required')
 require(f['passed']is True and f['whole_kernel_verified']is True and f['no_component_vo_reused']is True,'Complete sourcefresh whole proof required')
 require((run/'status.json').read_bytes()==(case/'proof/full-status.json').read_bytes(),'Original/public full status differs')
 require(f['handoff_sha256']==sha(case/'proof/frozen-full-handoff.json')and f['input_sha256']==h['frozen_source_sha256'],'Frozen H/full source binding differs');check_inputs(case,f['input_sha256']);require(f['config_sha256']==h['coq_config_sha256'] and f['limits']==h['limits'],'Frozen config/scope differs')
 require(f['parallel_jobs']==32 and f['ordinary_per_process_memory_GiB']==16 and f['heavy_per_process_memory_GiB']==32,'Resource profile differs')
 units=f['actual_c_units'];strategies=f['strategies'];require(len(units)==len(h['units'])==f['checked_c_units']==13 and f['checked_c_vcs']==h['total_actual_c_vcs']==1748,'Actual C accounting differs');require(h['actual_c_function_count']==19,'Ordinary C body count differs')
 require(len(strategies)==len(h['strategies'])==1 and f['checked_strategy_fields']==h['total_strategy_fields']==4,'Complete map strategy required')
 require(f['checked_second_c_fields']==1748 and f['checked_second_strategy_fields']==4,'Independent full second interfaces required')
 rows={r['label']:r for r in f['records']};require(len(rows)==len(f['records'])and all(r['exit_code']==0 for r in rows.values()),'Duplicate/missing/failed commands')
 artifacts=[];cpp={}
 for actual,expected in zip(units,h['units']):
  stem=expected['stem'];require(actual['namespace']==NS and actual['stem']==stem and actual['checked_module']==expected['typed_instance'],'Wrong actual provider '+stem)
  require(all(actual[k]==expected[k]for k in ['fields','goal_sha256','cpp_sha256']),'Actual goal/CPP/field binding '+stem)
  goal=run/'units'/stem/'generated'/(stem+'_goal.v');expanded=run/'units'/stem/'expanded.c';require(sha(goal)==actual['goal_sha256']and sha(expanded)==actual['cpp_sha256'],'Actual generated bytes drift '+stem)
  require(goal.read_bytes()==(run/'coq'/NS/goal.name).read_bytes(),'Compiled target differs '+stem);require(I.goal_fields(goal.read_text())==actual['fields'],'Actual complete goal fields differ '+stem)
  q=rows[stem+'-qcp']['command'];require('--arch=64'in q and '--endian=little'in q and '--input-file='+str(Path(f['run_directory'])/'units'/stem/(stem+'.c'))in q,'Actual QCP command binding differs '+stem)
  representation=I.definition_representation(expected);require(representation==actual['definition_representation']==expected['definition_representation'],'Definition policy changed '+stem)
  if representation['raw_def_emission']=='required':
   raw=run/'units'/stem/(stem+'_def.emitted.v.txt');adapter=run/'coq'/NS/(stem+'_def.v');require(sha(raw)==sha(goal.parent/(stem+'_def.v'))==representation['emitted_sha256']and sha(adapter)==representation['compiled_definition_sha256'],'Raw/canonical record representation mismatch '+stem);artifacts.extend([(raw,Path('units')/stem/raw.name),(adapter,Path('units')/stem/adapter.name)])
  else:require(not list(goal.parent.glob('*_def.v'))and not(run/'coq'/NS/(stem+'_def.v')).exists(),'Fabricated scalar def '+stem)
  cpp[stem]=expanded;artifacts.extend([(expanded,Path('units')/stem/'expanded.c'),(goal,Path('units')/stem/'goal.v')])
 for a,e in zip(strategies,h['strategies']):
  require(a['stem']==e['stem']=='hc_maps_strategy_goal'and a['fields']==e['field_names']and a['checked_module']==e['typed_instance'],'Actual strategy binding differs');path=run/'coq'/NS/'hc_maps_strategy_goal.v';require(sha(path)==e['goal_sha256'],'Actual strategy target differs');require('strategy-hc_maps_strategy_goal'in rows,'Actual strategy generator record missing')
 source=run/'coq'/NS
 generated=G.sources(NS,units,strategies);generated['FinalCaseCheck']=G.final_source(NS,units,strategies)
 for name,text in generated.items():require((source/(name+'.v')).read_text()==text,'Complete typed/observation/report/final gate differs '+name)
 compiled=f['compiled_source_sha256'];expected={NS+'.'+n for n in set(h['own_modules'])|set(generated)};require(set(compiled)==expected and len(compiled)==f['fresh_compiled_local_modules'],'Exact fresh source inventory differs')
 ordinary={};reports=[]
 for label,r in rows.items():
  cmd=r['command'];mem=r['memory_limit_GiB'];require(mem in {16,32}and cmd[:3]==['prlimit','--as='+str(mem*1024**3)+':'+str(mem*1024**3),'--']and 0<r['timeout_seconds']<=21600,'Finite command profile differs '+label)
  log=run/(label+'.log');require(sha(log)==r['log_sha256'],'Execution log drift '+label)
  if 'coqc'in cmd:
   require(cmd[3:5]==['qcp-env','coqc']and not any(a.startswith(('-vos','-vok','-quick','-vio'))for a in cmd),'Ordinary Coq only');flags=[s for s in cmd[5:-1]if s!='-time'];require('-time'in cmd and flags==h['coq_flags']+['-Q',str(Path(f['run_directory'])/'coq'/NS),NS],'Actual private Coq flags differ')
   logical=NS+'.'+Path(cmd[-1]).stem;require(logical not in ordinary and logical in expected,'Unexpected/duplicate Coq source '+logical);p=source/(Path(cmd[-1]).stem+'.v');require(Path(cmd[-1])==Path(f['run_directory'])/'coq'/NS/p.name and sha(p)==compiled[logical],'Compiled actual source drift '+logical)
   ordinary[logical]=r;reports+=assumptions.audit(p,log);artifacts.append((p,Path('coq')/NS/p.name))
 require(set(ordinary)==expected,'Missing actual ordinary compile command')
 own_generated={u['stem']+'_goal'for u in units}|{u['stem']+'_def'for u in units if u['definition_representation']['raw_def_emission']=='required'}|{'hc_maps_strategy_goal'}
 for n in h['own_modules']:
  if n not in own_generated:require(sha(source/(n+'.v'))==sha(case/'proof/coq'/(n+'.v')),'Compiled/public producer source differs '+n)
 names=G.identifiers(NS,units,strategies);require(len(names)==len(set(names))==3514,'Final complete report set differs');require(sha(run/G.REPORT)==f['final_assumptions_log_sha256'] and sha(source/'FinalCaseCheck.v')==f['final_gate_sha256'],'Final actual gate/report bytes drift')
 expected_parts=[]
 for i in range(16):
  name=G.PREFIX+str(i);records=[r for logical,r in ordinary.items()if logical==NS+'.'+name];require(len(records)==1,'Final report part not compiled '+name);actual=assumptions.audit(source/(name+'.v'),run/(records[0]['label']+'.log'));require([r['constant']for r in actual]==names[i::16],'Actual final Print partition differs '+name);expected_parts.extend(actual)
 require((run/G.REPORT).read_bytes()==b''.join((run/(ordinary[NS+'.'+G.PREFIX+str(i)]['label']+'.log')).read_bytes()for i in range(16)),'Aggregate final assumptions differ');require(f['final_assumptions_report_count']==len(expected_parts)==3514,'Final Print count differs')
 allowed=assumptions.CANONICAL;seen={a for r in reports for a in r['inherited_assumptions']};require(seen<=allowed and 'PropExtensionality.propositional_extensionality'not in seen,'New/unreviewed producer assumptions')
 import full_call_coverage
 closure=full_call_coverage.audit_sources(cpp,I.inventory(),read(case/'proof/intrinsic-ledger.json'),case);require(closure['passed']and closure['unique_ordinary_C_bodies']==19 and closure['terminal_intrinsic_count']==32 and closure['no_ordinary_body_exemptions'],'Actual ordinary body/call/intrinsic closure failed');require(closure==f['call_closure'],'Recorded ordinary body/call closure differs')
 external=external_dependencies.validate_external(case,run,f,require)
 dep=read(run/'coqdep-status.json');require(dep['exit_code']==0 and dep['stdout_sha256']==sha(run/'dependencies.mk')and dep['stderr_sha256']==sha(run/'coqdep.log'),'Actual dependency extraction differs')
 for n in ['external-before.v','external-before-locations.v','external-after.v','external-after-locations.v','external-dependencies.json','coqdep-status.json','dependencies.mk','coqdep.log']:
  if(run/n).exists():artifacts.append((run/n,Path(n)))
 return dict(passed=True,print_commands=3514,actual_C_print_commands=1748,second_actual_C_print_commands=1748,strategy_print_commands=4,second_strategy_print_commands=4,mathematical_support_print_commands=10,all_source_print_commands=len(reports),inherited_assumption_names=sorted(seen),new_project_axioms_observed=False,library_origin_audit=external),artifacts
